    AND t.id = #{bo.id}

        AND (t.brand LIKE CONCAT('%', #{bo.deviceName}, '%')
             OR t.model_spec LIKE CONCAT('%', #{bo.deviceName}, '%')
             OR t.registration_code LIKE CONCAT('%', #{bo.deviceName}, '%'))


        AND t.device_type = CASE #{bo.deviceType} WHEN '自动扶梯' THEN 1 WHEN '垂直电梯' THEN 2 ELSE -1 END

    AND t.line_id = #{bo.lineId}
    AND t.station_id = #{bo.stationId}
    AND t.device_variety_code = #{bo.deviceVarietyCode}
    AND t.running_status = #{bo.runningStatus}
    AND t.brand LIKE CONCAT('%', #{bo.brand}, '%')
    AND t.registration_code LIKE CONCAT('%', #{bo.registrationCode}, '%')
    AND t.model_spec LIKE CONCAT('%', #{bo.modelSpec}, '%')
    AND t.location_detail LIKE CONCAT('%', #{bo.locationDetail}, '%')
    AND t.remark LIKE CONCAT('%', #{bo.remark}, '%')

ORDER BY t.line_id ASC, t.station_id ASC, t.id ASC
